import {mountBuildingBlockEditor} from './building-block-editor.js?v=navigation-data-1';
import {REPLACEABLE_STYLES} from './building-art.js?v=navigation-data-1';
import {defaultBuildingDesign,validateBuildingDesign,applyBuildingDesign,exportBuildingDesign,importBuildingDesign,drawBuildingDesign} from './building-designs.js?v=navigation-data-1';
export function showBuildingDesigner({city,dialog,apply,close},initialSource=2){
 const $=id=>document.getElementById(id);let source=Number(initialSource),rotation=0,draft=structuredClone(city.buildingDesigns?.[source]||defaultBuildingDesign());
 dialog('Building designer',`<p>Create a building model and apply it to a residential or commercial tower style. You can design before your city has towers; the model appears when that style develops. This changes appearance, with the existing lot’s population, jobs and costs.</p><div class="building-designer"><div><canvas id="designPreview" width="256" height="384" aria-label="Custom tower preview"></canvas><button id="rotateDesign">Rotate preview · North</button></div><div><label>Replace tower style<select id="designSource">${Object.entries(REPLACEABLE_STYLES).map(([key,v])=>`<option value="${key}" ${Number(key)===source?'selected':''}>${v.name}</option>`).join('')}</select></label><label>Design name<input id="designName" maxlength="40"></label><label>Floors (4–24)<input id="designFloors" type="number" min="4" max="24" step="1"></label><label>Width (6–10)<input id="designWidth" type="range" min="6" max="10" step="1"></label><label>Depth (6–10)<input id="designDepth" type="range" min="6" max="10" step="1"></label><label>Roof<select id="designRoof"><option value="flat">Flat</option><option value="step">Stepped upper floors</option><option value="spire">Spire</option></select></label><div class="actions"><label>Facade<input id="designFacade" type="color"></label><label>Windows<input id="designWindows" type="color"></label><label>Accents<input id="designAccent" type="color"></label></div><div id="buildingBlockEditor"></div></div></div><p id="designStatus" role="status"></p><div class="actions"><button id="applyDesign" class="primary">Apply to city</button><button id="removeDesign">Use original artwork</button><button id="exportDesign">Export building file</button><button id="importDesign">Import building file</button><input id="designFile" type="file" accept=".json,application/json" hidden><button id="closeDesign">Close</button></div><p class="fine">One custom model per tower style, saved with this city. Imported files open as a draft until applied. Building files use SIMS3000’s own compact model format; original game building files, overhangs and individual floor painting are not supported yet.</p>`);
 let blockEditor;const canvas=$('designPreview'),fields={name:'designName',floors:'designFloors',width:'designWidth',depth:'designDepth',roof:'designRoof',facade:'designFacade',windows:'designWindows',accent:'designAccent'};
 function render(){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,256,384);drawBuildingDesign(ctx,draft,rotation);$('rotateDesign').textContent='Rotate preview · '+['North','East','South','West'][rotation];$('removeDesign').disabled=!city.buildingDesigns?.[source];}
 function fill(){for(const [key,id]of Object.entries(fields))$(id).value=draft[key];blockEditor?.reset();render();}
 function read(){return validateBuildingDesign({...Object.fromEntries(Object.entries(fields).map(([key,id])=>[key,['floors','width','depth'].includes(key)?Number($(id).value):$(id).value])),...(draft.blocks?{blocks:draft.blocks,...(draft.materials?{materials:draft.materials}:{})}:{})});}
 for(const id of Object.values(fields))$(id).oninput=()=>{try{draft=read();$('designStatus').textContent='Preview only · apply when ready.';render();}catch(e){$('designStatus').textContent=e.message;}};
 $('rotateDesign').onclick=()=>{rotation=(rotation+1)%4;render();};$('designSource').onchange=()=>{source=Number($('designSource').value);draft=structuredClone(city.buildingDesigns?.[source]||defaultBuildingDesign());fill();$('designStatus').textContent='Loaded this style’s saved model, or a fresh draft.';};
 $('applyDesign').onclick=()=>{try{draft=read();applyBuildingDesign(city,source,draft);apply();render();$('designStatus').textContent='Applied to this city. Current and future buildings of the selected style use this model.';}catch(e){$('designStatus').textContent=e.message;}};
 $('removeDesign').onclick=()=>{delete city.buildingDesigns[source];delete city.buildingReplacements[source];apply();render();$('designStatus').textContent='Original artwork restored for this style.';};
 $('exportDesign').onclick=()=>{try{const data=exportBuildingDesign(read()),url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='sims3000-building.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('designStatus').textContent='Building file exported.';}catch(e){$('designStatus').textContent=e.message;}};
 $('importDesign').onclick=()=>$('designFile').click();$('designFile').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>8192)throw Error('Building files must be smaller than 8 KB.');const imported=importBuildingDesign(await file.text());if(!document.contains(canvas))return;draft=imported;fill();$('designStatus').textContent='Imported as a draft. Apply to city when ready.';}catch(e){if(document.contains(canvas))$('designStatus').textContent=e.message;}finally{event.target.value='';}};
 blockEditor=mountBuildingBlockEditor($('buildingBlockEditor'),{get:()=>draft,set:next=>{draft=next;render();$('designStatus').textContent='Preview only · apply when ready.';}});$('closeDesign').onclick=close;fill();
}
